===== CheckEmailUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a new owner whose lower-cased email is already used by another owner, so the request is
 * answered with a 409 Conflict rather than persisting a duplicate. Runs after {@link ValidateNewOwner}
 * (which has already lower-cased the request email) and before {@link BuildOwner}.
 *
 * <p>Email is optional: a request without an email (null or blank) is left alone. Stored emails are
 * lower-cased the same way before comparison so seed data stored in mixed case still collides with an
 * equivalent request.
 */
public class CheckEmailUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String normalized = email.toLowerCase(Locale.ROOT);
        for (Owner existing : ownerRepository.findAll()) {
            String existingEmail = existing.getEmail();
            if (existingEmail != null
                    && normalized.equals(existingEmail.toLowerCase(Locale.ROOT))) {
                throw new DuplicateEmailException(normalized);
            }
        }
    }
}
===== CheckTelephoneUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a new owner whose E.164 telephone is already used by another owner, so the request is
 * answered with a 409 Conflict rather than persisting a duplicate. Runs after {@link ValidateNewOwner}
 * (which has already normalized the request telephone to E.164) and before {@link BuildOwner}.
 *
 * <p>Stored telephones are normalized to E.164 the same way before comparison so seed data that was
 * not stored in E.164 form still collides with an equivalent request.
 */
public class CheckTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            String existingTelephone = existing.getTelephone();
            if (existingTelephone != null
                    && telephone.equals(OwnerTelephone.toE164(existingTelephone))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===== CheckHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a new owner who belongs to the same household as an existing owner — same last name and same
 * address — so the request is answered with a 409 Conflict rather than persisting a duplicate household
 * member. Last name and address are compared case-insensitively with surrounding and internal whitespace
 * collapsed, so "Smith" / " smith " and "10  Main St" / "10 Main St" collide.
 *
 * <p>The caller can opt in to sharing a household by setting {@code sharesHousehold} true on the request,
 * which skips this check (e.g. a spouse or flatmate registering under the same roof). Runs after
 * {@link CheckTelephoneUnique} and before {@link BuildOwner}.
 */
public class CheckHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = Household.key(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(Household.key(existing.getLastName(), existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code householdId} — a stable identifier derived from the normalized last name
 * and address (see {@link Household}). Because the derivation is deterministic, every owner at the same
 * household (including one that joined an existing household via {@code sharesHousehold}) receives the
 * same value, which is then persisted and returned.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Household.id(owner.getLastName(), owner.getAddress()));
    }
}
===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Single source of truth for household identity. A household groups owners that share the same last
 * name and the same address, compared case-insensitively with surrounding and internal whitespace
 * collapsed (so "Smith" / " smith " and "10  Main St" / "10 Main St" belong together).
 *
 * <p>The {@link #id(String, String)} derived from that normalized pair is stable: the same last name
 * and address always map to the same value, so every member of a household — including one that joins
 * via {@code sharesHousehold} — receives an identical {@code householdId}.
 */
final class Household {

    private Household() {
    }

    /** Lower-case (locale-independent) with leading/trailing and repeated internal whitespace collapsed. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * The canonical household key for a (lastName, address) pair — the single definition of household
     * membership. Two owners belong to the same household exactly when their keys are equal; {@link #id}
     * hashes this same key, so the duplicate check and the assigned id can never diverge.
     *
     * <p>Addresses are compared in their {@link OwnerAddress normalized} form (whitespace collapsed,
     * upper-cased, abbreviations expanded) so that equivalent spellings — "12 main st" and
     * "12 MAIN STREET" — belong to the same household even when stored data was not normalized.
     */
    static String key(String lastName, String address) {
        return normalize(lastName) + "\n" + OwnerAddress.normalize(address);
    }

    /**
     * Stable household identifier for the given last name and address: {@code "H-"} followed by the
     * first 12 hex characters of the SHA-256 of the {@link #key household key}.
     */
    static String id(String lastName, String address) {
        String key = key(lastName, address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("H-");
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
===== OwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Single source of truth for what a "normalized" owner telephone is: the E.164 form. Both
 * {@link ValidateNewOwner} (which enforces the rule and stores the E.164 value) and
 * {@link CheckTelephoneUnique} (which compares against stored owners) normalize through here, so the
 * two cannot drift apart.
 *
 * <p>Normalization strips spaces, dashes and brackets, then forms the canonical E.164 string:
 * <ul>
 *   <li>a leading {@code '+'} and country code are kept as-is;</li>
 *   <li>otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
 *       the national digits.</li>
 * </ul>
 * The result must be a {@code '+'} followed by 8 to 15 digits. On top of that general rule, the
 * national-number length (the digits after the country code) must match the country code when it is one
 * we recognize: {@code +61} requires 9 national digits and {@code +1} requires 10 (see
 * {@link #NATIONAL_LENGTHS}). Anything else — non-digit leftovers, a total digit count outside 8 to 15,
 * or a national-number length that is wrong for a recognized country code — is not valid E.164 and
 * yields {@code null}. A country code that is not in the table is accepted on the general rule alone.
 */
final class OwnerTelephone {

    /** A valid E.164 value: '+' then 8 to 15 digits. */
    private static final Pattern E164 = Pattern.compile("^\\+[0-9]{8,15}$");

    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");

    /**
     * Country code (without the '+') to its required national-number length. Iterated longest-code-first
     * (hence {@link LinkedHashMap}) so a longer code is matched before a shorter one that is a prefix of
     * the number. Country codes absent here are not length-checked.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS;
    static {
        Map<String, Integer> lengths = new LinkedHashMap<>();
        lengths.put("61", 9); // Australia
        lengths.put("1", 10); // North American Numbering Plan
        NATIONAL_LENGTHS = lengths;
    }

    private OwnerTelephone() {
    }

    /**
     * Returns the E.164 form of {@code telephone}, or {@code null} when it cannot form valid E.164.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = SEPARATORS.matcher(telephone).replaceAll("");
        String digits;
        if (cleaned.startsWith("+")) {
            // Keep the explicit country code; the '+' is re-added below.
            digits = cleaned.substring(1);
        }
        else {
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        String e164 = "+" + digits;
        if (!E164.matcher(e164).matches()) {
            return null;
        }
        return hasValidNationalLength(digits) ? e164 : null;
    }

    /**
     * Whether the national-number length of {@code digits} (a '+'-less E.164 digit string) matches its
     * country code. Unrecognized country codes pass (checked only by the general 8-to-15 rule above).
     */
    private static boolean hasValidNationalLength(String digits) {
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                return digits.length() - code.length() == entry.getValue();
            }
        }
        return true;
    }
}

