package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Single source of truth for an owner's {@code identityKey} — the one derived value all duplicate
 * detection is now expressed through. The key is
 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}, so two owners are
 * duplicates exactly when their whole keys are equal.
 *
 * <p>Because the normalized telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed; only an
 * exact full-key match is a duplicate.
 *
 * <p>Every component is taken in its canonical form so stored data that was not normalized still
 * collides with an equivalent request: the telephone as E.164 (see {@link OwnerTelephone}), the email
 * lower-cased (empty when absent), and the household id derived from last name and address (see
 * {@link Household}). {@link #of(String, String, String, String)} computes the key straight from an
 * owner's raw fields so the create check and the returned value can never diverge.
 */
final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * The identity key for the given raw owner fields: the telephone normalized to E.164, the email
     * lower-cased (or empty when null/blank), and the household id derived from last name and address,
     * joined by {@code '|'}. A telephone that is not valid E.164 contributes an empty telephone
     * component rather than failing — validation happens elsewhere.
     */
    static String of(String telephone, String email, String lastName, String address) {
        String e164 = OwnerTelephone.toE164(telephone);
        String householdId = Household.id(lastName, address);
        return key(e164, email, householdId);
    }

    /**
     * Assembles the key from already-derived components: a normalized (E.164) telephone, an email and a
     * household id. Null telephone or household id become empty; a null or blank email becomes empty,
     * and a present email is lower-cased.
     */
    static String key(String normalizedTelephone, String email, String householdId) {
        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
        String household = householdId == null ? "" : householdId;
        return tel + "|" + mail + "|" + household;
    }
}

