package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate check for a new owner. All duplicate detection is consolidated into one derived
 * {@code identityKey} (see {@link OwnerIdentity}): a new owner is rejected with a 409 Conflict only when
 * its WHOLE identity key — normalized telephone, email and household id together — equals an existing
 * owner's. This replaces the separate telephone, email and household checks: because the telephone is
 * part of the key, two members of the same household with different telephones now have different keys
 * and are both allowed; only an exact full-key match is a duplicate.
 *
 * <p>Runs after {@link ValidateNewOwner} (which has normalized the request telephone to E.164 and
 * lower-cased the email) and before {@link BuildOwner}. Existing owners are compared in their canonical
 * form so seed data that was not normalized still collides with an equivalent request.
 */
public class CheckIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.of(request.getTelephone(), request.getEmail(),
                request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            String existingKey = OwnerIdentity.of(existing.getTelephone(), existing.getEmail(),
                    existing.getLastName(), existing.getAddress());
            if (identityKey.equals(existingKey)) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

