package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Single source of truth for an owner's {@code identityKey} — the one derived value all duplicate
 * detection is now expressed through. The key is
 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}, so two owners are
 * duplicates exactly when their whole keys are equal.
 *
 * <p>Because the normalized telephone is part of the key, two members of the same household with
 * different telephones have different keys and are both allowed; only an exact full-key match is a
 * duplicate.
 *
 * <p>Every component is taken in its canonical form so stored data that was not normalized still
 * collides with an equivalent request: the telephone as E.164 (see {@link OwnerTelephone}), the email
 * lower-cased (empty when absent), and the {@code householdId} as assigned. The {@code householdId} is
 * derived and assigned only once an owner is created, so when a key is built for the create-time
 * uniqueness check it is not yet known and the household component is empty for both the candidate and
 * the owners it is compared against (see {@link CheckIdentityUnique}); the key returned on a created
 * owner carries its assigned {@code householdId}.
 */
final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * The identity key for the given owner fields: the telephone normalized to E.164 (empty when it is
     * not valid E.164 — validation happens elsewhere), the email lower-cased (empty when null/blank),
     * and the {@code householdId} (empty when null/blank), joined by {@code '|'}.
     */
    static String of(String telephone, String email, String householdId) {
        String tel = OwnerTelephone.toE164(telephone);
        String telPart = tel == null ? "" : tel;
        String mailPart = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
        String householdPart = (householdId == null || householdId.isBlank()) ? "" : householdId;
        return telPart + "|" + mailPart + "|" + householdPart;
    }
}

